import datetime, hashlib, html, json, pathlib
R=pathlib.Path(__file__).parent;P=R/'public';P.mkdir(exist_ok=True)
checks=json.loads((R/'evidence/public-checks.json').read_text());by={x['url']:x for x in checks}
date=max(x['checked_at'] for x in checks)
routes=[
 {'url':'https://faces.valkrai.com/','name':'Faces Lab','kind':'Interactive studio','description':'Shape an original adult mannequin with editable proportions, reversible sculpt dabs and geometry comparisons. A procedural form study with stated limits.','type':'page'},
 {'url':'https://valkrais.valkrai.com/','name':'Character atelier','kind':'Concept gallery','description':'Explore winged studies of Eir, Brynhildr and Skuld. Compare the concepts, inspect the artwork and read its provenance. Concepts are not approved visual canon.','type':'page'},
 {'url':'https://valkrai.com/','name':'Valkrai homepage','kind':'Venture brief · utility','description':'The current public venture brief, with a manual-input track-fusion calculator. The page is separate from the character and face studies.','type':'page'},
 {'url':'https://faces.valkrai.com/about','name':'Method & provenance','kind':'Behind the studio','description':'How the Faces Lab represents geometry, measures changes and preserves edits. Read the scope and limitations of the authored surfaces.','type':'page'}]
metadata=[('https://faces.valkrai.com/build.json','Faces build manifest'),('https://valkrais.valkrai.com/provenance.json','Gallery provenance'),('https://valkrai.com/health','Homepage hosting health'),('https://valkrai.com/sitemap.xml','Homepage sitemap'),('https://valkrai.com/robots.txt','Homepage crawl policy'),('https://faces.valkrai.com/robots.txt','Faces crawl policy'),('https://valkrais.valkrai.com/robots.txt','Gallery crawl policy')]
for r in routes:
 c=by[r['url']];assert c['status']==200 and c['title'];r.update(status='Page verified',http_status=c['status'],checked_at=c['checked_at'],title=c['title'],sha256=c['sha256'])
for url,name in metadata:
 c=by[url];assert c['status']==200;routes.append(dict(url=url,name=name,type='metadata',status='Responding',http_status=200,checked_at=c['checked_at'],sha256=c['sha256']))
public={'schema':'valkrai-public-directory/1.0','checked_at':date,'pages':4,'primary_hosts':3,'routes':routes,'aliases':[{'url':'https://faces.valkrai.com/about.html','canonical':'https://faces.valkrai.com/about','note':'Hosting redirects the HTML filename to its canonical extensionless page.'},{'url':'https://www.valkrai.com/','canonical':'https://valkrai.com/','note':'Same title and response SHA-256 at check time.'},{'url':'https://valkrai.com/index.html','canonical':'https://valkrai.com/','note':'Same title and response SHA-256 at check time.'}],'section_links':[{'url':'https://valkrais.valkrai.com/'+a,'type':'section'} for a in ['#collection','#compare','#vitruvian','#origins','#versions']]+[{'url':'https://valkrai.com/#fusion-form','type':'section'}],'coverage':['Known public page routes from current hosting records, published HTML links, source files and public manifests.','GET identity checks include distinctive titles and headings, SHA-256, and missing-path controls. No form submissions or calculator runs.','DNS-record API access was denied. Other DNS-only hostnames may exist; this is a bounded inventory, not proof every subdomain has been found.','Private/admin routes, unpublished work, archive copies, APIs that can mutate state, and individual implementation assets are outside the visitor page directory.','A response check is not a full feature test or an uptime guarantee. This is a dated snapshot, not a live monitor.']}
(P/'inventory.json').write_text(json.dumps(public,indent=2,ensure_ascii=False)+'\n')
icons={
 'faces':'<path d="M110 20c-33 0-47 27-43 57 3 22 18 48 43 55 25-7 40-33 43-55 4-30-10-57-43-57Z"/><path d="M76 63q15-13 29 0m10 0q15-13 29 0M110 64l-7 29 13 0m-23 15q17 10 34 0M84 41q26-14 52 0"/><path d="M84 121l-6 25m58-25 6 25"/>',
 'gallery':'<path d="M110 37v100m-8-85-13-17-29-8 23 30-35-15 24 30-37-12 35 33-37-7 51 34m34-68 13-17 29-8-23 30 35-15-24 30 37-12-35 33 37-7-51 34"/><circle cx="110" cy="26" r="9"/><path d="M93 139h34m-26-72-10 37m28-37 10 37"/>',
 'brief':'<circle cx="110" cy="80" r="52"/><ellipse cx="110" cy="80" rx="24" ry="52"/><path d="M58 80h104m-96-25h88m-88 50h88M110 28v104M41 42l137 76M49 121 170 36"/><circle cx="80" cy="64" r="5" fill="#72978c"/><circle cx="145" cy="100" r="5" fill="#72978c"/>',
 'method':'<path d="M75 28h70v100H75zM88 47h44M88 61h44M88 75h27M88 94h44M88 108h32"/>'}
visuals=list(icons)
cards=[]
for i,r in enumerate(routes[:4]):
 key=visuals[i];sub=''
 if i==1: sub='<nav class="subroutes" aria-label="Gallery sections"><a href="https://valkrais.valkrai.com/#collection">Collection</a><a href="https://valkrais.valkrai.com/#compare">Compare</a><a href="https://valkrais.valkrai.com/#vitruvian">Wing anatomy</a><a href="https://valkrais.valkrai.com/#origins">Origins</a><a href="https://valkrais.valkrai.com/#versions">Versions</a></nav>'
 if i==2: sub='<nav class="subroutes" aria-label="Homepage sections"><a href="https://valkrai.com/#fusion-form">Track-fusion calculator</a></nav>'
 cards.append(f'''<article class="card {'method-card' if i==3 else ''}" data-search="{html.escape(r['name']+' '+r['kind']+' '+r['description'])}"><div class="visual {key}" aria-hidden="true"><span class="index">0{i+1} / VALKRAI</span><svg viewBox="0 0 220 160" fill="none" stroke="{'#659084' if key=='brief' else '#8e799f'}" stroke-width="1.3" stroke-linejoin="round">{icons[key]}</svg></div><div class="card-body"><div class="card-top"><span class="kind">{r['kind']}</span><span class="badge">Page verified</span></div><h3>{r['name']}</h3><p>{r['description']}</p><div class="address">{r['url'].removeprefix('https://')}</div><a class="open" href="{r['url']}" aria-label="Open {r['name']}">Open {('method' if i==3 else 'site')}<span aria-hidden="true">↗</span></a>{sub}</div></article>''')
links=''.join(f'<a href="{u}">{html.escape(n)} ↗</a>' for u,n in metadata)
out=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f3f1e9"><meta name="description" content="A checked directory of public Valkrai pages: Faces Lab, character atelier, method and the current homepage. Includes verification dates and coverage limits."><title>Valkrai Routes — The public directory</title><link rel="icon" href="data:,"><link rel="stylesheet" href="style.css"></head><body>
<a class="skip" href="#directory">Skip to directory</a><div class="wrap"><header><a class="wordmark" href="/">valkrai<span>/ routes</span></a><div class="edition"><i class="dot" aria-hidden="true"></i>Public directory · 001</div></header>
<main><section class="hero" aria-labelledby="title"><div><p class="eyebrow">A small atlas of Valkrai</p><h1>Every public corner.<br><em>One way in.</em></h1><p class="lede">Find the studios, studies and tools that are open to explore. A checked map of the known public pages, with their purpose and limits in view.</p></div><div class="atlas" aria-hidden="true"><i></i><i></i><i></i><svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.2"><path d="M24 8v33M21 15 4 8l10 14-11-4 17 17m7-20L44 8 34 22l11-4-17 17"/></svg><small>THE PUBLIC ATLAS</small></div></section>
<div class="checkline"><span><i class="dot" aria-hidden="true"></i><b>4 distinct pages</b> · 3 destination hosts</span><span>Last checked <b><time datetime="{date}">{date[:10]} · {date[11:16]} UTC</time></b></span><span>Snapshot · page identity verified</span></div>
<section id="directory" aria-labelledby="directory-title"><div class="section-heading"><div><h2 id="directory-title">Choose your destination<span id="result-count" aria-live="polite"></span></h2><p>Separate experiences, connected by Valkrai.</p></div><div class="tools" hidden id="search-tools"><label><span class="sr-only">Search destinations</span><input class="search" id="search" type="search" placeholder="Search this directory…" autocomplete="off"></label></div></div><div class="grid">{''.join(cards)}</div><p class="empty" id="empty" hidden>No matching destination. Try “faces”, “gallery” or “method”.</p></section>
<div class="detail-grid"><section aria-labelledby="checked-title"><p class="eyebrow">Grounded in the page</p><h2 id="checked-title">What “verified” means here</h2><p>Each destination returned its expected title and distinct page content. Missing-path controls returned 404. Links to gallery sections were checked against published section IDs.</p><p>These checks confirm page identity and reachability at the time shown. They do not certify every interactive feature, visual quality or continued uptime.</p><details class="details"><summary>Public metadata & supporting records</summary><div class="resources">{links}<a href="inventory.json">Download this route inventory (JSON)</a></div></details></section>
<section aria-labelledby="coverage-title"><p class="eyebrow">A map with honest edges</p><h2 id="coverage-title">Coverage & boundaries</h2><p>Built from the current hosting routes and custom hostnames, published links, source files and public manifests. The directory itself is separate from the four destination pages.</p><ul><li><strong>Aliases:</strong> www.valkrai.com and /index.html currently serve the same homepage.</li><li><strong>Not listed:</strong> private or admin pages, unpublished work, archive copies, state-changing APIs and individual code or image assets.</li><li><strong>Coverage limit:</strong> DNS inventory access was denied. Other DNS-only hostnames may exist; this is not an exhaustive subdomain scan.</li></ul><div class="note">This is a dated snapshot, not an automatic status monitor. The character atelier contains concept proposals; the Faces Lab is a procedural study.</div></section></div></main>
<footer><span>Valkrai / Public directory</span><span>Read-only · No accounts, uploads or tracking</span><a href="inventory.json">Route inventory ↗</a></footer></div><script src="app.js" defer></script></body></html>'''
(P/'index.html').write_text(out)
(P/'app.js').write_text('''"use strict";
const search=document.querySelector("#search"),cards=[...document.querySelectorAll(".card")];
document.querySelector("#search-tools").hidden=false;
search.addEventListener("input",()=>{const query=search.value.trim().toLowerCase();let count=0;for(const card of cards){card.hidden=!card.dataset.search.toLowerCase().includes(query);if(!card.hidden)count++;}document.querySelector("#result-count").textContent=query?`${count} of ${cards.length}`:"";document.querySelector("#empty").hidden=count!==0;});
''')
(P/'404.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found — Valkrai Routes</title><style>body{font:18px system-ui;background:#f3f1e9;color:#262534;padding:8vw;max-width:700px}a{color:#7254bf}</style><h1>That route is not in this directory.</h1><p><a href="/">Return to Valkrai Routes</a></p></html>')
(P/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://routes.valkrai.com/sitemap.xml\n')
(P/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://routes.valkrai.com/</loc></url></urlset>\n')
(P/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src \'self\'; script-src \'self\'; style-src \'self\'; img-src \'self\' data:; connect-src \'none\'; object-src \'none\'; base-uri \'none\'; frame-ancestors \'none\'\n  Cache-Control: public, max-age=300, must-revalidate\n')
manifest={p.relative_to(P).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(P.rglob('*')) if p.is_file()}
(R/'evidence/release-manifest.json').write_text(json.dumps({'files':manifest,'checked_at':date},indent=2)+'\n')
print(f'Built {len(manifest)} public files; four page destinations, seven metadata records.')
